// does s[i:] match p[j:] ?
private boolean solve(String s, String p, int i, int j) {
    if (j == p.length()) {
        return i == s.length();
    }
    if (p.charAt(j) == '*') {
        // match one more char of s (star stays) OR match empty (skip star)
        if (i < s.length() && solve(s, p, i + 1, j)) {
            return true;
        }
        return solve(s, p, i, j + 1);
    }
    if (i < s.length() && (p.charAt(j) == '?' || p.charAt(j) == s.charAt(i))) {
        return solve(s, p, i + 1, j + 1);
    }
    return false;
}

