def is_match(self, s: str, p: str) -> bool:
    n, m = len(s), len(p)

    def solve(i: int, j: int) -> bool:
        if j == m:
            return i == n
        if p[j] == '*':
            # match one more char of s (star stays) OR match empty (skip star)
            if i < n and solve(i + 1, j):
                return True
            return solve(i, j + 1)
        if i < n and (p[j] == '?' or p[j] == s[i]):
            return solve(i + 1, j + 1)
        return False

    return solve(0, 0)

