public boolean isMatch(String s, String p) {
    int n = s.length(), m = p.length();
    Boolean[][] memo = new Boolean[n + 1][m + 1];
    return solve(s, p, 0, 0, memo);
}

private boolean solve(String s, String p, int i, int j, Boolean[][] memo) {
    if (j == p.length()) {
        return i == s.length();
    }
    if (memo[i][j] != null) {
        return memo[i][j];
    }
    boolean ans;
    if (p.charAt(j) == '*') {
        ans = (i < s.length() && solve(s, p, i + 1, j, memo))
              || solve(s, p, i, j + 1, memo);
    } else if (i < s.length() && (p.charAt(j) == '?' || p.charAt(j) == s.charAt(i))) {
        ans = solve(s, p, i + 1, j + 1, memo);
    } else {
        ans = false;
    }
    memo[i][j] = ans;
    return ans;
}

