import sys

def is_match(self, s: str, p: str) -> bool:
    sys.setrecursionlimit(10000)  # depth can reach n + m (~4000)
    n, m = len(s), len(p)
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def solve(i: int, j: int) -> bool:
        if j == m:
            return i == n
        if p[j] == '*':
            return (i < n and solve(i + 1, j)) or solve(i, j + 1)
        if i < n and (p[j] == '?' or p[j] == s[i]):
            return solve(i + 1, j + 1)
        return False

    return solve(0, 0)

